SET
  content = '{"level_id":"4.10","badge_name":"কাজের কারিগর","level_title":"এলটি (LT) লাইনের ফেজ ব্যালেন্সিং","mission_briefing":"একটি থ্রি-ফেজ সিস্টেমের আদর্শ অবস্থা হলো, যখন তিনটি ফেজ (R, Y, B) প্রায় সমানভাবে লোড বা কারেন্ট বহন করে। কিন্তু বাস্তবে, সিঙ্গেল-ফেজ গ্রাহকদের সংযোগ এলোমেলোভাবে হওয়ার কারণে প্রায়ই একটি ফেজের ওপর অন্যগুলোর চেয়ে অনেক বেশি চাপ পড়ে। এই অবস্থাকে ''লোড আনব্যালেন্স'' বলে। এর ফলে ওভারলোডিং, লো-ভোল্টেজ এবং নিউট্রালে কারেন্ট প্রবাহের মতো সমস্যা দেখা দেয়। এই লেভেলের মিশন হলো, একজন দক্ষ সিস্টেম ম্যানেজারের মতো এই আনব্যালেন্স সনাক্ত করা এবং লোডকে পুনরায় ভাগ করে সিস্টেমে ভারসাম্য ফিরিয়ে আনা।","sections":[{"title":"সিস্টেমে ভারসাম্য ফিরিয়ে আনা","points":[{"item_name":"১. লোড আনব্যালেন্স কেন একটি সমস্যা?","specifications":"• একটি ফেজ ওভারলোডেড: যে ফেজটিতে বেশি লোড থাকে, সেই ফেজের ফিউজ বারবার উড়ে যেতে পারে বা ট্রান্সফরমারের ওয়াইন্ডিং অতিরিক্ত গরম হতে পারে।\n• লো-ভোল্টেজ: ওভারলোডেড ফেজের গ্রাহকরা লো-ভোল্টেজের সমস্যায় ভোগেন, আর কম লোডযুক্ত ফেজের গ্রাহকরা হাই-ভোল্টেজ পেতে পারেন।\n• নিউট্রালে কারেন্ট প্রবাহ: একটি ব্যালেন্সড সিস্টেমে নিউট্রালে কোনো কারেন্ট থাকে না। কিন্তু আনব্যালেন্সড সিস্টেমে নিউট্রাল তার দিয়ে কারেন্ট প্রবাহিত হয়, যা সিস্টেমের লস বাড়ায় এবং বিপজ্জনক হতে পারে।\n• ট্রান্সফরমারের অদক্ষতা: আনব্যালেন্সড লোড একটি ট্রান্সফরমারের পূর্ণ ক্ষমতা ব্যবহার করতে দেয় না এবং এর কার্যকারিতা কমিয়ে দেয়।","importance":"লোড ব্যালেন্সিং সিস্টেমের স্বাস্থ্য, নির্ভরযোগ্যতা এবং দীর্ঘস্থায়ীত্ব—সবকিছুর জন্যই অত্যন্ত জরুরি।","image_name":"/images/loader/bal410_why.webp","image_caption":"আনব্যালেন্স সমস্যা"},{"item_name":"২. আনব্যালেন্স সনাক্ত করার উপায়","specifications":"• ক্ল্যাম্প-অন মিটার (Clamp-on Meter / Tong Tester): এটিই লোড ব্যালেন্সিং-এর প্রধান হাতিয়ার। ট্রান্সফরমারের এলটি বুশিং বা ফিডার পিলারের বাসবার থেকে বেরোনো প্রতিটি ফেজের তারে (R, Y, B) এবং নিউট্রাল তারে ক্ল্যাম্প করে সরাসরি অ্যাম্পিয়ারে কারেন্টের মান পরিমাপ করুন।\n• লক্ষণ পর্যবেক্ষণ: যদি কোনো একটি নির্দিষ্ট এলাকার গ্রাহকরা বারবার লো-ভোল্টেজের অভিযোগ করেন বা একটি নির্দিষ্ট ফেজের ফিউজ বারবার উড়ে যায়, তবে এটি আনব্যালেন্সের একটি স্পষ্ট লক্ষণ।","importance":"সঠিক পরিমাপ ছাড়া লোড ব্যালেন্সিং করা অনুমানের ওপর কাজ করার মতো। ক্ল্যাম্প মিটার আপনাকে সিস্টেমের আসল চিত্রটি দেখায়।","image_name":"/images/loader/bal410_clamp.webp","image_caption":"ক্ল্যাম্প দিয়ে মাপা"},{"item_name":"৩. লোড ব্যালেন্স করার পদ্ধতি","specifications":"• ধাপ ১ (পরিমাপ): প্রথমে, পিক-লোড সময়ে প্রতিটি ফেজ এবং নিউট্রালের কারেন্ট মেপে একটি তালিকা তৈরি করুন। (যেমন R=120A, Y=70A, B=50A, N=50A)।\n• ধাপ ২ (পরিকল্পনা): সনাক্ত করুন কোন ফেজটি ওভারলোডেড (এখানে R) এবং কোনগুলো কম লোডযুক্ত (Y, B)। এবার পরিকল্পনা করুন যে ওভারলোডেড ফেজের কোন কোন গ্রাহকের সার্ভিস লাইনকে কম লোডযুক্ত ফেজে স্থানান্তর করা যায়।\n• ধাপ ৩ (কাজ): সঠিক PTW এবং সুরক্ষা নিয়ম মেনে, ফিডার পিলার বা পোলের ওপর সার্ভিস লাইনগুলোর ফেজ কানেকশন পরিবর্তন করুন।\n• ধাপ ৪ (পুনঃপরীক্ষা): কাজ শেষ হওয়ার পর, আবার ক্ল্যাম্প মিটার দিয়ে প্রতিটি ফেজের কারেন্ট মেপে দেখুন লোড কতটা ব্যালেন্সড হয়েছে।","importance":"এটি একটি ধারাবাহিক প্রক্রিয়া। সময়ের সাথে সাথে নতুন গ্রাহক যুক্ত হলে বা লোডের ধরন পরিবর্তন হলে আবার আনব্যালেন্স তৈরি হতে পারে, তাই নির্দিষ্ট সময় অন্তর এটি পরীক্ষা করা উচিত।","image_name":"/images/loader/bal410_rework.webp","image_caption":"লোড ভাগ · ফেজ শিফট"}],"image_name":"/images/loader/bal410_why.webp","image_caption":"আনব্যালেন্স সমস্যা"}],"image_suggestion":"একটি ইনফোগ্রাফিক। প্রথম অংশে একটি ক্ল্যাম্প মিটার দিয়ে ফিডার পিলারের তিনটি ফেজের (R, Y, B) কারেন্ট মাপা হচ্ছে, যেখানে রিডিংগুলো আনব্যালেন্সড (যেমন 120A, 70A, 50A)। দ্বিতীয় অংশে কিছু সার্ভিস কানেকশনের ফেজ পরিবর্তন করার একটি ডায়াগ্রাম দেখানো হয়েছে। তৃতীয় অংশে আবার কারেন্ট মাপা হচ্ছে, যেখানে রিডিংগুলো প্রায় ব্যালেন্সড (যেমন 85A, 80A, 75A)।","pro_tip":{"title":"বিশেষ প্রো টিপস (Pro Tips)","content":["১. নিউট্রাল কারেন্ট লক্ষ্য করুন: নিউট্রাল কারেন্টের মান আপনার আনব্যালেন্সের একটি সরাসরি প্রমাণ। নিউট্রাল কারেন্ট যত বেশি, সিস্টেম তত বেশি আনব্যালেন্সড। আপনার লক্ষ্য হলো নিউট্রাল কারেন্টকে যতটা সম্ভব শূন্যের কাছাকাছি আনা।","২. বড় লোড দিয়ে শুরু করুন: ব্যালেন্স করার সময়, প্রথমে বড় থ্রি-ফেজ লোডগুলো (যেমন কোনো ওয়ার্কশপ) ঠিকমতো ব্যালেন্সড আছে কিনা দেখুন। তারপর সিঙ্গেল-ফেজ লোডগুলোকে ভাগ করুন।","৩. রেকর্ড রাখুন: কোন গ্রাহককে কোন ফেজে সংযোগ করা আছে, তার একটি রেকর্ড বা ডায়াগ্রাম তৈরি করে রাখলে ভবিষ্যতের কাজ অনেক সহজ হয়ে যায়।","৪. গ্রাহককে জানান: যদি কোনো গ্রাহকের সংযোগ পরিবর্তনের প্রয়োজন হয়, তবে সম্ভব হলে তাকে আগে থেকে জানিয়ে রাখুন।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"নিউট্রালে তো কোনো ভোল্টেজ থাকে না, তাই ওতে কারেন্টও থাকে না।","reality":"ভুল। এটি শুধুমাত্র একটি সম্পূর্ণ ব্যালেন্সড থ্রি-ফেজ সিস্টেমের ক্ষেত্রেই সত্য। বাস্তবে, প্রায় সমস্ত ডিস্ট্রিবিউশন সিস্টেমে কম-বেশি আনব্যালেন্স থাকে এবং নিউট্রাল তার দিয়ে উল্লেখযোগ্য পরিমাণে কারেন্ট প্রবাহিত হয়।"},{"myth":"লোড ব্যালেন্সিং একটা কঠিন এবং সময়সাপেক্ষ কাজ, এর তেমন কোনো লাভ নেই।","reality":"একেবারেই নয়। লোড ব্যালেন্সিং সিস্টেমের লস কমায়, ট্রান্সফরমারের আয়ু বাড়ায়, ভোল্টেজের গুণমান উন্নত করে এবং ব্রেকডাউন কমায়। এটি সিস্টেমের নির্ভরযোগ্যতা বাড়ানোর অন্যতম সেরা উপায়।"}],"image_name":"/images/loader/bal410_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · ব্যালেন্স"},"advanced_section":{"title":"এর পেছনের ইঞ্জিনিয়ারিং ফ্যাক্টস","facts":[{"title":"ভেক্টর যোগফল (Vector Sum)","content":"একটি ব্যালেন্সড থ্রি-ফেজ সিস্টেমে, তিনটি ফেজের কারেন্টের মধ্যে ১২০-ডিগ্রীর ফেজ পার্থক্য থাকে। এর ফলে, যেকোনো মুহূর্তে তাদের ভেক্টর যোগফল শূন্য হয়, তাই নিউট্রালে কোনো কারেন্ট ফেরে না। কিন্তু যখন লোড আনব্যালেন্সড হয়, তখন এই ভেক্টর যোগফল আর শূন্য থাকে না, এবং এই অবশিষ্ট কারেন্টটিই নিউট্রাল তার দিয়ে প্রবাহিত হয়।"},{"title":"ট্রান্সফরমারের ডি-রেটিং (Transformer De-rating)","content":"একটি ১০০ কেভিএ ট্রান্সফরমারকে যদি খুব বেশি আনব্যালেন্সড লোড দেওয়া হয়, তবে একটি ফেজ ওভারলোডেড হয়ে যাওয়ার কারণে সেটিকে হয়তো ৭০ বা ৮০ কেভিএ-এর বেশি লোড দেওয়া সম্ভব হয় না। অর্থাৎ, আনব্যালেন্সের কারণে ট্রান্সফরমারটিকে তার পূর্ণ ক্ষমতার চেয়ে কম ক্ষমতায় (De-rated) চালাতে হয়, যা একটি অর্থনৈতিক ক্ষতি।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '4.10' AND language = 'bn';

