UPDATE training_chapters
SET
  content = '{"level_id":"5.10","badge_name":"ফল্ট ফাইন্ডার","level_title":"প্রিভেন্টিভ মেইনটেন্যান্স: গোয়েন্দা থেকে ডাক্তার","mission_briefing":"একজন ভালো গোয়েন্দা শুধু অপরাধীকে ধরেই না, সে অপরাধ ঘটার আগেই তা আটকানোর চেষ্টা করে। ''ফল্ট ফাইন্ডার'' ব্যাজের এই চূড়ান্ত অধ্যায়ে, আপনি শিখবেন কীভাবে একজন গোয়েন্দার পাশাপাশি একজন ডাক্তার হতে হয়। প্রিভেন্টিভ বা প্রতিরোধমূলক রক্ষণাবেক্ষণ হলো সিস্টেমের নিয়মিত স্বাস্থ্য পরীক্ষা করা, যাতে কোনো ছোট সমস্যা বড় রোগে পরিণত হওয়ার আগেই তার চিকিৎসা করা যায়। এই লেভেলের মিশন হলো, ''ব্রেকডাউন''-এর জন্য অপেক্ষা না করে, একটি সুস্থ এবং নির্ভরযোগ্য নেটওয়ার্ক বজায় রাখার কৌশলগুলো শেখা।","sections":[{"title":"রোগের আগে প্রতিরোধ: একটি সুস্থ নেটওয়ার্কের চাবিকাঠি","points":[{"item_name":"১. প্রিভেন্টিভ মেইনটেন্যান্স (PM) কী?","specifications":"এটি হলো একটি পরিকল্পিত এবং নিয়মিত রক্ষণাবেক্ষণের কর্মসূচি, যার উদ্দেশ্য হলো সরঞ্জাম খারাপ হওয়ার বা ফল্ট ঘটার সম্ভাবনাকে কমানো। এটি ''ব্রেকডাউন মেইনটেন্যান্স'' (অর্থাৎ, খারাপ হওয়ার পর সারানো)-এর ঠিক উল্টো।","importance":"PM সিস্টেমের নির্ভরযোগ্যতা বাড়ায়, সরঞ্জামের আয়ু বাড়ায়, বড় ধরনের এবং ব্যয়বহুল ব্রেকডাউন কমায় এবং সামগ্রিকভাবে সুরক্ষা উন্নত করে। একটি পরিকল্পিত শাটডাউন একটি অপরিকল্পিত ব্ল্যাকআউটের চেয়ে সবসময়ই ভালো।","pro_tip":"আপনার কোম্পানির একটি বার্ষিক বা ষাণ্মাসিক PM শিডিউল থাকে। সেই শিডিউল সম্পর্কে অবগত থাকুন।","image_name":"/images/loader/pm510_what.webp","image_caption":"PM কী"},{"item_name":"২. লাইনম্যানের পিএম (PM) চেকলিস্ট","specifications":"একটি সাধারণ পিএম শিডিউলের সময় একজন লাইনম্যানকে এই কাজগুলো করতে হয়:\n• চাক্ষুষ পরিদর্শন: সম্পূর্ণ লাইন এবং সরঞ্জাম (পোল, কন্ডাক্টর, ইনসুলেটর, হার্ডওয়্যার) পুঙ্খানুপুঙ্খভাবে পরীক্ষা করা।\n• হটস্পট সনাক্তকরণ: থার্মাল ক্যামেরা দিয়ে সমস্ত কানেকশন, জয়েন্ট এবং সরঞ্জাম স্ক্যান করে লুজ কানেকশন বা ওভারলোডেড অংশ খুঁজে বের করা।\n• কানেকশন টাইট করা: সমস্ত জাম্পার, সার্ভিস কানেকশন এবং হার্ডওয়্যারের নাট-বল্টু পরীক্ষা করা এবং প্রয়োজন অনুযায়ী টাইট দেওয়া।\n• ট্রি ট্রিমিং: লাইনের কাছাকাছি চলে আসা গাছের ডালপালা ছাঁটা।\n• আর্থিং পরীক্ষা: সমস্ত আর্থিং কানেকশন পরীক্ষা করা এবং প্রয়োজনে আর্থ পিটের রক্ষণাবেক্ষণ করা।\n• সরঞ্জাম পরিষ্কার করা: ইনসুলেটর, বুশিং এবং অন্যান্য সরঞ্জাম পরিষ্কার করা।","importance":"এই কাজগুলো একটি সিস্টেমের প্রায় ৯০% সাধারণ ফল্টের কারণগুলোকে গোড়াতেই নষ্ট করে দেয়।","image_name":"/images/loader/pm510_check.webp","image_caption":"লাইনম্যান চেকলিস্ট"},{"item_name":"৩. কন্ডিশন-বেসড মেইনটেন্যান্স (Condition-Based Maintenance - CBM)","specifications":"এটি পিএম-এর একটি উন্নত রূপ। এখানে নির্দিষ্ট সময় অন্তর রক্ষণাবেক্ষণ না করে, সরঞ্জামের ''স্বাস্থ্য'' বা ''কন্ডিশন'' ক্রমাগত পর্যবেক্ষণ করা হয় এবং যখন প্রয়োজন, তখনই রক্ষণাবেক্ষণ করা হয়।\n• উদাহরণ: ট্রান্সফরমার তেলের DGA টেস্ট, ইনসুলেটরের করোনা স্ক্যান, বা কেবিলের পার্শিয়াল ডিসচার্জ (PD) টেস্ট।","importance":"এটি অপ্রয়োজনীয় রক্ষণাবেক্ষণ কমায় এবং সঠিক সময়ে সঠিক কাজ করতে সাহায্য করে, যা আরও বেশি কার্যকর এবং অর্থনৈতিক।","pro_tip":"একজন লাইনম্যান হিসেবে, আপনি যখন কোনো সরঞ্জামের অবস্থার অবনতি (যেমন তেলের রং পরিবর্তন, অস্বাভাবিক শব্দ) লক্ষ্য করেন এবং রিপোর্ট করেন, তখন আপনিও CBM-এর একটি গুরুত্বপূর্ণ অংশ হয়ে ওঠেন।","image_name":"/images/loader/pm510_cbm.webp","image_caption":"কন্ডিশন-বেসড"}],"image_name":"/images/loader/pm510_what.webp","image_caption":"PM কী"}],"image_suggestion":"একটি চক্রাকার ডায়াগ্রাম। চক্রের একপাশে লেখা ''ব্রেকডাউন মেইনটেন্যান্স'' (একটি ভাঙা ট্রান্সফরমারের ছবি এবং একটি প্রশ্ন চিহ্ন)। অন্যপাশে লেখা ''প্রিভেন্টিভ মেইনটেন্যান্স'' (একজন লাইনম্যান থার্মাল ক্যামেরা দিয়ে একটি সুস্থ ট্রান্সফরমার পরীক্ষা করছেন এবং একটি সবুজ টিক চিহ্ন)। চক্রটি দেখাচ্ছে কীভাবে পিএম করলে ব্রেকডাউনের সম্ভাবনা কমে যায়।","pro_tip":{"title":"বিশেষ প্রো টিপস (Pro Tips)","content":["১. ছোট সমস্যাকে অবহেলা করবেন না: পিএম-এর সময় একটি সামান্য লুজ নাট বা হালকা মরিচা ধরা ক্ল্যাম্প দেখলে, সেটিকে তখনই ঠিক করুন। ''পরে করা যাবে''—এই মনোভাবই বড় ব্রেকডাউনের জন্ম দেয়।","২. রেকর্ড রাখুন: আপনি পিএম-এর সময় কী কী কাজ করলেন এবং কী কী অস্বাভাবিকতা পেলেন, তা একটি লগবুকে বা ডিজিটাল অ্যাপে রেকর্ড করে রাখুন। এই ডেটা ভবিষ্যতের পরিকল্পনার জন্য অমূল্য।","৩. সঠিক টুলস ব্যবহার করুন: পিএম-এর কার্যকারিতা সঠিক টুলসের ওপর নির্ভর করে। একটি ভালো টর্ক রেঞ্চ, থার্মাল ক্যামেরা বা আর্থ টেস্টার আপনার কাজকে অনেক বেশি নির্ভুল করে তোলে।","৪. শিখতে থাকুন: নতুন প্রযুক্তি এবং রক্ষণাবেক্ষণের কৌশল সম্পর্কে নিজেকে আপডেট রাখুন। এটি আপনাকে একজন সাধারণ লাইনম্যান থেকে একজন সিস্টেম বিশেষজ্ঞ করে তুলবে।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"যে জিনিসটা ঠিকঠাক চলছে, সেটাকে খোলার বা নাড়াচাড়া করার দরকার কী? এতে তো বরং সমস্যা তৈরি হতে পারে।","reality":"ভুল। অনেক সমস্যাই (যেমন লুজ কানেকশন, ইনসুলেশন দুর্বল হওয়া) বাইরে থেকে বোঝা যায় না এবং அவை ধীরে ধীরে বড় হতে থাকে। পিএম এই লুকানো সমস্যাগুলোকেই খুঁজে বের করে এবং একটি আকস্মিক ব্রেকডাউন প্রতিরোধ করে।"},{"myth":"প্রিভেন্টিভ মেইনটেন্যান্স মানে শুধু লাইন পরিষ্কার করা।","reality":"না। পরিষ্কার করা পিএম-এর একটি অংশ মাত্র। আসল কাজ হলো निरीक्षण, परीक्षण এবং विश्लेषण-এর মাধ্যমে একটি সরঞ্জামের স্বাস্থ্যের মূল্যায়ন করা এবং প্রয়োজনীয় ব্যবস্থা নেওয়া।"}],"image_name":"/images/loader/pm510_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · PM"},"advanced_section":{"title":"এর পেছনের ইঞ্জিনিয়ারিং ফ্যাক্টস","facts":[{"title":"রিলায়েবিলিটি-সেন্টার্ড মেইনটেন্যান্স (RCM - Reliability-Centered Maintenance)","content":"এটি একটি অত্যন্ত উন্নত রক্ষণাবেক্ষণ দর্শন, যা বড় শিল্প বা পাওয়ার প্ল্যান্টে ব্যবহৃত হয়। এখানে প্রতিটি সরঞ্জামের ''ফেলিওর মোড'' বা কীভাবে এটি খারাপ হতে পারে তা বিশ্লেষণ করা হয়। তারপর, সেই নির্দিষ্ট ফেলিওরটি প্রতিরোধ করার জন্য সবচেয়ে কার্যকর রক্ষণাবেক্ষণ কৌশল (PM, CBM, বা অন্য কোনো কৌশল) বেছে নেওয়া হয়। এর মূল লক্ষ্য হলো, ন্যূনতম খরচে সিস্টেমের সর্বোচ্চ নির্ভরযোগ্যতা অর্জন করা।"},{"title":"বাথটাব কার্ভ (Bathtub Curve)","content":"এটি একটি গ্রাফ যা একটি সরঞ্জামের জীবনকালে তার ফেলিওরের হার দেখায়। শুরুতে, উৎপাদনগত ত্রুটির কারণে ফেলিওরের হার বেশি থাকে (Infant mortality)। তারপর, একটি দীর্ঘ সময় ধরে ফেলিওরের হার খুব কম এবং স্থির থাকে (Useful life)। অবশেষে, পুরনো হয়ে যাওয়ার কারণে ফেলিওরের হার আবার বাড়তে শুরু করে (Wear-out phase)। প্রিভেন্টিভ মেইনটেন্যান্সের প্রধান লক্ষ্য হলো এই ''Useful life'' বা কার্যকরী জীবনকালকে যতটা সম্ভব দীর্ঘ করা।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '5.10' AND language = 'bn';

