UPDATE training_chapters
SET
  content = '{"level_id":"6.11","badge_name":"যন্ত্র গুরু","level_title":"আর্থিং সিস্টেম: অদৃশ্য অভিভাবক","mission_briefing":"বিদ্যুৎ সিস্টেমে এমন একজন অদৃশ্য রক্ষক আছে যাকে চোখে দেখা যায় না, কিন্তু তার অনুপস্থিতি মারাত্মক বিপদ ডেকে আনতে পারে। সে হলো আর্থিং বা গ্রাউন্ডিং। এটি ফল্টের সময় বিদ্যুৎকে মাটিতে যাওয়ার একটি নিরাপদ পথ করে দিয়ে মানুষ এবং যন্ত্রপাতি উভয়কেই রক্ষা করে। একটি দুর্বল আর্থিং মানে সুরক্ষার ভিত্তিটাই নড়বড়ে। এই লেভেলের মিশন হলো, এই অদৃশ্য অভিভাবককে চেনা, তার বিভিন্ন রূপ জানা এবং তার স্বাস্থ্য পরীক্ষা ও রক্ষণাবেক্ষণ করতে শেখা।","sections":[{"title":"সুরক্ষার ভিত্তি: গঠন ও রক্ষণাবেক্ষণ","points":[{"item_name":"১. আর্থিং-এর দ্বৈত ভূমিকা: কেন এত গুরুত্বপূর্ণ?","specifications":"আর্থিং-এর দুটি প্রধান উদ্দেশ্য:\n• সরঞ্জামের সুরক্ষা (Equipment Earthing): ট্রান্সফরমার, পোল বা ফিডার পিলারের মতো যন্ত্রপাতির ধাতব বডিকে আর্থ করা থাকে। যদি কোনো কারণে ভেতরের লাইভ তার বডির সংস্পর্শে আসে, তবে আর্থিং একটি লো-রেজিস্ট্যান্স পথ তৈরি করে দেয়, যার মধ্যে দিয়ে प्रचंड কারেন্ট প্রবাহিত হয় এবং ফিউজ বা ব্রেকার ট্রিপ করে।\n• সিস্টেমের স্থিতিশীলতা (System Earthing): ট্রান্সফরমারের নিউট্রাল পয়েন্টকে আর্থ করা হয়। এটি পুরো সিস্টেমের ভোল্টেজকে মাটির সাপেক্ষে স্থিতিশীল রাখে এবং ফল্টের সময় সুরক্ষা রিলেকে সঠিকভাবে কাজ করতে সাহায্য করে।","importance":"এক কথায়, আর্থিং ছাড়া কোনো সুরক্ষা ডিভাইস (ফিউজ, ব্রেকার, LA) সঠিকভাবে কাজ করতে পারে না। এটিই সম্পূর্ণ সুরক্ষা সিস্টেমের ভিত্তি।","image_name":"/images/loader/earth611_role.webp","image_caption":"দ্বৈত ভূমিকা"},{"item_name":"২. প্রকারভেদ: পাইপ এবং প্লেট আর্থিং","specifications":"ডিস্ট্রিবিউশন সিস্টেমে মূলত দুই ধরনের আর্থিং দেখা যায়:\n• পাইপ আর্থিং (Pipe Earthing): এটি সবচেয়ে সাধারণ পদ্ধতি। এখানে একটি নির্দিষ্ট দৈর্ঘ্যের (সাধারণত ২.৫-৩ মিটার) গ্যালভানাইজড আয়রনের (GI) ছিদ্রযুক্ত পাইপকে মাটিতে উল্লম্বভাবে পুঁতে দেওয়া হয়।\n• প্লেট আর্থিং (Plate Earthing): এখানে একটি নির্দিষ্ট আকারের (যেমন 60cm x 60cm) তামার বা GI-এর প্লেটকে মাটির গভীরে পুঁতে দেওয়া হয়। এটি সাধারণত সাবস্টেশন বা বড় ট্রান্সফরমারের ক্ষেত্রে ব্যবহৃত হয় যেখানে খুব কম রেজিস্ট্যান্স প্রয়োজন।","importance":"দুটি পদ্ধতিরই উদ্দেশ্য হলো মাটির সাথে একটি বিশাল পৃষ্ঠতলের সংযোগ তৈরি করা, যাতে ফল্ট কারেন্ট সহজেই মাটিতে ছড়িয়ে পড়তে পারে।","image_name":"/images/loader/earth611_types.webp","image_caption":"পাইপ ও প্লেট"},{"item_name":"৩. একটি সুস্থ আর্থিং সিস্টেমের লক্ষণ","specifications":"• আর্থ স্ট্রিপ/ওয়্যার: আর্থিং তার বা পাতটি কোথাও কাটা, ছেঁড়া বা অতিরিক্ত মরিচা ধরা উচিত নয়।\n• কানেকশন পয়েন্ট: আর্থিং তারটি যেখানে সরঞ্জামের বডির সাথে এবং নিচে আর্থ ইলেক্ট্রোডের সাথে সংযুক্ত হয়েছে, সেই কানেকশনগুলো অত্যন্ত মজবুত, পরিষ্কার এবং টাইট হওয়া আবশ্যক। সাধারণত নাট-বল্টু বা ওয়েল্ডিং করে এই সংযোগ করা হয়।\n• আর্থ পিট: আর্থিং পিট বা গর্তের চারপাশ পরিষ্কার এবং একটি কংক্রিটের চেম্বার দিয়ে সুরক্ষিত থাকা উচিত। এর ঢাকনাটি ঠিকমতো লাগানো থাকবে।","importance":"বেশিরভাগ আর্থিং সমস্যাই এই কানেকশন পয়েন্টগুলোতে হয়। একটি লুজ বা মরিচা ধরা কানেকশন আর্থিং-এর রেজিস্ট্যান্স বহুগুণ বাড়িয়ে দেয়, যা পুরো সিস্টেমকে অকেজো করে দেয়। আর্থিং তার চুরি হয়ে যাওয়া একটি বড় সমস্যা।","daily_check":"লাইন পেট্রোলিং-এর সময় প্রতিটি পোলের আর্থিং কানেকশন চাক্ষুষভাবে পরীক্ষা করা একটি আবশ্যক রুটিন।","image_name":"/images/loader/earth611_health.webp","image_caption":"সুস্থ আর্থিং"},{"item_name":"৪. রক্ষণাবেক্ষণ: শক্তি ফিরিয়ে আনা","specifications":"• কানেকশন টাইট করা: সমস্ত লুজ কানেকশন একটি ব্রাশ দিয়ে পরিষ্কার করে এবং পেট্রোলিয়াম জেলি বা গ্রিজ লাগিয়ে টাইট দিন।\n• জল দেওয়া: শুকনো আবহাওয়ায়, বিশেষ করে পাইপ আর্থিং-এর ক্ষেত্রে, পিটের মধ্যে দিয়ে জল দিলে চারপাশের মাটির আর্দ্রতা বাড়ে এবং আর্থ রেজিস্ট্যান্স কমে।\n• লবণ ও কয়লা: আর্থ পিট তৈরি করার সময় বা রক্ষণাবেক্ষণের সময়, ইলেক্ট্রোডের চারপাশে কাঠকয়লা এবং লবণের স্তর দেওয়া হয়। এটি মাটির পরিবাহিতা (Conductivity) বাড়াতে এবং আর্দ্রতা ধরে রাখতে সাহায্য করে।","importance":"নিয়মিত এবং সঠিক রক্ষণাবেক্ষণের মাধ্যমে একটি পুরনো এবং দুর্বল আর্থিং সিস্টেমকেও আবার কার্যকর করে তোলা যায়।","image_name":"/images/loader/earth611_health.webp","image_caption":"রক্ষণাবেক্ষণ"}],"image_name":"/images/loader/earth611_role.webp","image_caption":"দ্বৈত ভূমিকা"}],"image_suggestion":"একটি পাইপ আর্থিং-এর ক্রস-সেকশনাল ডায়াগ্রাম, যেখানে আর্থ ইলেক্ট্রোড, কাঠকয়লা ও লবণের স্তর এবং জল দেওয়ার জন্য ফানেল স্পষ্টভাবে দেখানো হয়েছে। পাশে একটি ট্রান্সফরমারের ছবি থাকবে, যেখানে ''বডি আর্থিং'' এবং ''নিউট্রাল আর্থিং''—দুটি আলাদা আর্থ কানেকশন চিহ্নিত করা থাকবে।","pro_tip":{"title":"বিশেষ প্রো টিপস (Pro Tips)","content":["১. ডাবল আর্থিং: ট্রান্সফরমারের মতো গুরুত্বপূর্ণ সরঞ্জামগুলোকে সুরক্ষার জন্য সবসময় দুটি আলাদা আর্থ পিট থেকে ডাবল আর্থিং করা হয়। একটি ব্যর্থ হলেও অন্যটি সুরক্ষা দেবে।","২. মরিচা বিপদ: আর্থিং কানেকশনে সাধারণ নাট-বল্টুর বদলে পিতল বা স্টেইনলেস স্টিলের নাট-বল্টু ব্যবহার করা উচিত, কারণ এগুলিতে সহজে মরিচা ধরে না।","৩. মাটি একটি ফ্যাক্টর: পাথুরে বা বালুকাময় মাটির রেজিস্ট্যান্স বেশি হয়, তাই সেখানে ভালো আর্থিং পাওয়া কঠিন। এই ধরনের জায়গায় একাধিক ইলেক্ট্রোড ব্যবহার করতে হয় বা মাটির রাসায়নিক ট্রিটমেন্ট (Bentonite powder) করতে হয়।","৪. আর্থ রেজিস্ট্যান্স টেস্টিং: একটি ''আর্থ মেগার'' ব্যবহার করে আর্থিং-এর রেজিস্ট্যান্স মাপাটাই এর স্বাস্থ্য পরীক্ষার সবচেয়ে নির্ভরযোগ্য উপায়। এই মানটি নির্দিষ্ট সীমার (যেমন ৫ ওহম) মধ্যে থাকা উচিত।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"আর্থিং তারটা তো শুধু সুরক্ষার জন্য, ওটা একটু কাটা বা আলগা থাকলেও লাইন চলতে কোনো অসুবিধা হয় না।","reality":"মারাত্মক ভুল। লাইন স্বাভাবিক অবস্থায় চলবে, কিন্তু ফল্টের সময় আর্থিং কাজ না করলে সার্কিট ব্রেকার ট্রিপ করবে না এবং একটি ছোট সমস্যা একটি বড় বিপর্যয় বা প্রাণহানির কারণ হয়ে দাঁড়াবে।"},{"myth":"যেকোনো একটি লোহার রড মাটিতে পুঁতে দিলেই ভালো আর্থিং হয়ে যায়।","reality":"না। একটি কার্যকর আর্থিং-এর জন্য সঠিক উপাদান (যেমন GI বা কপার), সঠিক দৈর্ঘ্য, সঠিক ইনস্টলেশন পদ্ধতি এবং চারপাশের মাটির অবস্থা—সবকিছুই গুরুত্বপূর্ণ। এটি একটি বিজ্ঞান, শুধু একটি রড পুঁতে দেওয়া নয়।"}],"image_name":"/images/loader/earth611_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · আর্থিং"},"advanced_section":{"title":"এর পেছনের ইঞ্জিনিয়ারিং ফ্যাক্টস","facts":[{"title":"টাচ এবং স্টেপ পটেনশিয়াল (Touch and Step Potential)","content":"ফল্টের সময় যখন प्रचंड কারেন্ট মাটিতে যায়, তখন আর্থ ইলেক্ট্রোডের চারপাশের মাটিতে একটি ভোল্টেজ গ্রেডিয়েন্ট তৈরি হয়। আপনি যদি সেই মুহূর্তে ফল্টি সরঞ্জামটিকে স্পর্শ করেন, তবে আপনার হাত এবং পায়ের মধ্যে যে ভোল্টেজ পার্থক্য তৈরি হয় তাকে ''টাচ পটেনশিয়াল'' বলে। আর আপনার দুই পায়ের মধ্যে যে ভোল্টেজ পার্থক্য তৈরি হয় তাকে ''স্টেপ পটেনশিয়াল'' বলে। এই দুটিই মারাত্মক শকের কারণ হতে পারে। সাবস্টেশনের সুইচইয়ার্ডে পাথরের কুচি (Gravel) দেওয়া হয় মাটির পৃষ্ঠের রেজিস্ট্যান্স বাড়িয়ে এই বিপদ কমানোর জন্য।"},{"title":"আর্থ ম্যাট (Earth Mat)","content":"বড় সাবস্টেশনগুলোতে, মাটির নিচে তামার বা স্টিলের পরিবাহীর একটি বিশাল জাল (Grid or Mat) বিছানো থাকে। এটি ফল্ট কারেন্টকে একটি বিশাল এলাকা জুড়ে ছড়িয়ে দিয়ে টাচ এবং স্টেপ পটেনশিয়ালকে নিরাপদ সীমার মধ্যে রাখে এবং একটি অত্যন্ত নির্ভরযোগ্য লো-রেজিস্ট্যান্স আর্থিং সিস্টেম তৈরি করে।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '6.11' AND language = 'bn';
